#include <stdio.h>
#include <string.h>

#define N 10
#define RANGE 101      /* 关键字范围 [0,100] */
#define RADIX 10

void counting_sort(int a[], int n) {
    int cnt[RANGE];
    int out[N];
    memset(cnt, 0, sizeof(cnt));
    for (int i = 0; i < n; i++) cnt[a[i]]++;          /* 统计 */
    for (int i = 1; i < RANGE; i++) cnt[i] += cnt[i - 1];  /* 前缀和 -> 稳定位置 */
    for (int i = n - 1; i >= 0; i--) {                /* 逆序填保证稳定 */
        out[--cnt[a[i]]] = a[i];
    }
    for (int i = 0; i < n; i++) a[i] = out[i];
}

/* 基数排序 LSD：从个位到高位，每趟用稳定排序 */
void radix_sort(int a[], int n) {
    for (int exp = 1; exp <= 100; exp *= 10) {
        int cnt[RADIX], out[N];
        memset(cnt, 0, sizeof(cnt));
        for (int i = 0; i < n; i++) cnt[(a[i] / exp) % RADIX]++;
        for (int i = 1; i < RADIX; i++) cnt[i] += cnt[i - 1];
        for (int i = n - 1; i >= 0; i--) {
            int d = (a[i] / exp) % RADIX;
            out[--cnt[d]] = a[i];
        }
        for (int i = 0; i < n; i++) a[i] = out[i];
        printf("按 %d 位排序后:", exp);
        for (int i = 0; i < n; i++) printf(" %d", a[i]);
        printf("\n");
    }
}

int main(void) {
    int a[] = {65, 27, 49, 38, 97, 76, 13, 49, 100, 4};
    int b[N];
    memcpy(b, a, sizeof(a));

    printf("原始序列:");
    for (int i = 0; i < N; i++) printf(" %d", a[i]);
    printf("\n\n--- 计数排序 O(n+k), k=%d ---\n", RANGE);
    counting_sort(a, N);
    for (int i = 0; i < N; i++) printf(" %d", a[i]);
    printf("\n\n--- 基数排序 LSD O(d(n+r)) ---\n");
    radix_sort(b, N);
    printf("最终:");
    for (int i = 0; i < N; i++) printf(" %d", b[i]);
    printf("\n\n两者都不基于比较 -> 不受 Omega(n log n) 下界约束\n");
    printf("前提: 关键字是小范围整数 / 可按位分解；代价: 额外 O(n+r) 空间\n");
    return 0;
}
